package com.shopsphere.controller;import com.shopsphere.model.Product;import com.shopsphere.repository.ProductRepository;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/products")public class ProductController{private final ProductRepository repo;public ProductController(ProductRepository r){repo=r;}@GetMapping public List<Product> all(){return repo.findAll();}@GetMapping("/{id}")public Product one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Product not found"));}@PostMapping @PreAuthorize("hasRole('ADMIN')")public Product create(@Valid @RequestBody Product p){return repo.save(p);}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public Product update(@PathVariable Long id,@Valid @RequestBody Product p){Product x=one(id);x.setName(p.getName());x.setCategory(p.getCategory());x.setPrice(p.getPrice());x.setStock(p.getStock());x.setDescription(p.getDescription());return repo.save(x);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public void delete(@PathVariable Long id){repo.delete(one(id));}}